import sys
from typing import List, Tuple

def compute_area(x1: float, y1: float, x2: float, y2: float) -> float:
    return (x2 - x1) * (y2 + y1) / 2

def find_bulkheads(C: int, vertices: List[Tuple[float, float]]) -> List[float]:
    n = len(vertices)
    total_area = 0.0
    for i in range(n):
        total_area += compute_area(vertices[i][0], vertices[i][1], vertices[(i + 1) % n][0], vertices[(i + 1) % n][1])

    target_area = total_area / C
    bulkheads = []

    def check(x: float) -> bool:
        area = 0.0
        for i in range(n):
            if vertices[i][0] <= x < vertices[(i + 1) % n][0]:
                area += compute_area(vertices[i][0], vertices[i][1], x, vertices[i][1])
                area += compute_area(x, vertices[i][1], vertices[(i + 1) % n][0], vertices[(i + 1) % n][1])
            else:
                area += compute_area(vertices[i][0], vertices[i][1], vertices[(i + 1) % n][0], vertices[(i + 1) % n][1])
            if area >= target_area:
                return True
        return False

    for _ in range(C - 1):
        left, right = -1e5, 1e5
        while right - left > 1e-6:
            mid = (left + right) / 2
            if check(mid):
                right = mid
            else:
                left = mid
        bulkheads.append(right)

    return bulkheads

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    C = int(data[0])
    N = int(data[1])
    vertices = [(int(data[2 + 2 * i]), int(data[3 + 2 * i])) for i in range(N)]

    bulkheads = find_bulkheads(C, vertices)
    M = len(bulkheads) + 1
    print(M)
    for b in bulkheads:
        print(f"{b:.6f}")

if __name__ == "__main__":
    main()
